import { useId, useRef, type KeyboardEvent, type ReactNode } from "react";
import "./TabStrip.css";

export interface Tab {
  id: string;
  label: string;
}

export interface TabStripProps {
  tabs: readonly Tab[];
  selected: string;
  onSelect: (id: string) => void;
  children: ReactNode;
}

export function TabStrip({ tabs, selected, onSelect, children }: TabStripProps) {
  const baseId = useId();
  const buttonRefs = useRef<Map<string, HTMLButtonElement>>(new Map());

  const selectedIndex = tabs.findIndex((tab) => tab.id === selected);
  // If the selected id matches no tab, the first tab is the keyboard entry point.
  const activeId = selectedIndex >= 0 ? selected : tabs[0]?.id;
  const panelId = `${baseId}-panel`;

  const tabDomId = (id: string) => `${baseId}-tab-${id}`;

  const moveTo = (index: number) => {
    const target = tabs[index];
    if (!target) return;
    onSelect(target.id);
    buttonRefs.current.get(target.id)?.focus();
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const count = tabs.length;
    if (count === 0) return;

    const current = selectedIndex >= 0 ? selectedIndex : 0;

    switch (event.key) {
      case "ArrowRight":
        event.preventDefault();
        moveTo((current + 1) % count);
        break;
      case "ArrowLeft":
        event.preventDefault();
        moveTo((current - 1 + count) % count);
        break;
      case "Home":
        event.preventDefault();
        moveTo(0);
        break;
      case "End":
        event.preventDefault();
        moveTo(count - 1);
        break;
      default:
        break;
    }
  };

  const activeTab = tabs.find((tab) => tab.id === activeId);

  return (
    <div className="tab-strip">
      <div
        className="tab-strip__list"
        role="tablist"
        aria-orientation="horizontal"
        onKeyDown={handleKeyDown}
      >
        {tabs.map((tab) => {
          const isSelected = tab.id === activeId;
          return (
            <button
              key={tab.id}
              ref={(el) => {
                if (el) {
                  buttonRefs.current.set(tab.id, el);
                } else {
                  buttonRefs.current.delete(tab.id);
                }
              }}
              id={tabDomId(tab.id)}
              type="button"
              role="tab"
              className={
                isSelected ? "tab-strip__tab tab-strip__tab--selected" : "tab-strip__tab"
              }
              aria-selected={isSelected}
              aria-controls={panelId}
              tabIndex={isSelected ? 0 : -1}
              onClick={() => onSelect(tab.id)}
            >
              {tab.label}
            </button>
          );
        })}
      </div>

      <div
        id={panelId}
        className="tab-strip__panel"
        role="tabpanel"
        aria-labelledby={activeTab ? tabDomId(activeTab.id) : undefined}
        tabIndex={0}
      >
        {children}
      </div>
    </div>
  );
}
