/*
 * TabStrip styles for Myelin.
 *
 * Themes are selected with a data-theme attribute on an ancestor
 * (for example <html data-theme="night">). Day is the default.
 */

:root,
[data-theme="day"] {
  --tab-bg: #f6f5f1;
  --tab-border: #d9d6cc;
  --tab-fg: #2b2a26;
  --tab-muted: #6e6b61;
  --tab-hover-bg: #ecEAe2;
  --tab-accent: #3d7a6b;
  --tab-focus: #2f6a5c;
  --panel-bg: #fbfaf7;
  --panel-fg: #2b2a26;
}

[data-theme="night"] {
  --tab-bg: #171b21;
  --tab-border: #2a3039;
  --tab-fg: #d7dce3;
  --tab-muted: #8a93a1;
  --tab-hover-bg: #1f242c;
  --tab-accent: #7fb8a8;
  --tab-focus: #9cd3c3;
  --panel-bg: #13161b;
  --panel-fg: #d7dce3;
}

.tab-strip {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  background: var(--panel-bg);
  color: var(--panel-fg);
}

.tab-strip__list {
  display: flex;
  align-items: stretch;
  gap: 0.25rem;
  padding: 0 1rem;
  background: var(--tab-bg);
  border-bottom: 1px solid var(--tab-border);
  overflow-x: auto;
  flex-shrink: 0;
}

.tab-strip__tab {
  position: relative;
  appearance: none;
  border: none;
  background: transparent;
  color: var(--tab-muted);
  font: inherit;
  font-size: 0.95rem;
  font-weight: 400;
  line-height: 1;
  padding: 0.9rem 0.85rem 0.95rem;
  margin: 0;
  cursor: pointer;
  white-space: nowrap;
  border-radius: 6px 6px 0 0;
  transition: color 150ms ease, background-color 150ms ease;
}

.tab-strip__tab:hover {
  color: var(--tab-fg);
  background: var(--tab-hover-bg);
}

.tab-strip__tab--selected,
.tab-strip__tab--selected:hover {
  color: var(--tab-fg);
  font-weight: 600;
  background: transparent;
}

/* Underline marks the selected tab in addition to weight and color. */
.tab-strip__tab::after {
  content: "";
  position: absolute;
  left: 0.85rem;
  right: 0.85rem;
  bottom: 0;
  height: 2px;
  border-radius: 2px 2px 0 0;
  background: transparent;
  transition: background-color 150ms ease;
}

.tab-strip__tab--selected::after {
  background: var(--tab-accent);
}

.tab-strip__tab:focus {
  outline: none;
}

.tab-strip__tab:focus-visible {
  outline: 2px solid var(--tab-focus);
  outline-offset: -2px;
}

.tab-strip__panel {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  padding: 1.25rem 1.5rem;
}

.tab-strip__panel:focus {
  outline: none;
}

.tab-strip__panel:focus-visible {
  outline: 2px solid var(--tab-focus);
  outline-offset: -2px;
}

@media (prefers-reduced-motion: reduce) {
  .tab-strip__tab,
  .tab-strip__tab::after {
    transition: none;
  }
}
